"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { StuckReason, StuckBacklogItem } from "@/gen/session/v1/backlog_pb";
import {
  getStuckReasonClass,
  getStuckReasonIcon,
  getStuckReasonLabel,
  isPrStatusUnknown,
  formatStuckDuration,
  formatAgo,
  PR_STATUS_UNKNOWN_CLASS,
  PR_STATUS_UNKNOWN_ICON,
  PR_STATUS_UNKNOWN_LABEL,
} from "./stuckReason";
import { StuckItemDetail } from "./StuckItemDetail";
import { DuplicatePendingBadge } from "../backlog/DuplicatePendingBadge";
import { ClaimOverrideForm } from "@/components/backlog/ClaimOverrideForm";
import {
  useSnoozeControl,
  useRetryRemediation,
  useClaimOverrideControl,
  type SnoozeDuration,
} from "./useStuckItemCardActions";
import * as styles from "./StuckItem.css";

interface StuckItemProps {
  item: StuckBacklogItem;
  isExpanded: boolean;
  onToggleExpand: () => void;
  /** Count of *other* currently-visible reason groups this same item_id also appears in (design/ux.md Surface 2 cross-reference badge). 0 or omitted suppresses the badge. */
  otherReasonsCount?: number;
  otherReasonLabels?: string[];
  /** True once the underlying condition has resolved while this card was expanded (design/ux.md Surface 12). */
  justResolved?: boolean;
  resolvedMessage?: string;
  /** Overrides the default "It will be removed from this list shortly." trailing copy — used for de-escalation, where only this card (not the whole item) is going away. */
  resolvedTrailingMessage?: string;
  /** Imperative snooze action from useStuckBacklogItems — omitted disables the snooze control entirely. */
  onSnooze?: (itemId: string, reason: StuckReason, until: Date) => Promise<boolean>;
  /** Sets a per-item rework-cap override and immediately reopens the item — omitted disables the rework_cap override control. */
  onReworkCapOverride?: (itemId: string, override: number) => Promise<boolean>;
  /**
   * This item's current reworkCapOverride value, fetched by the parent via
   * getBacklogItem since StuckBacklogItem (this component's `item` prop type)
   * doesn't carry the field. undefined = not fetched yet / no override set,
   * 0 = unlimited, >0 = this item's own cap. Passed straight through to
   * StuckItemDetail for display — see StuckItemsSection.tsx's
   * `reworkCapOverrides` map for the fetch.
   */
  currentReworkCapOverride?: number;
  /**
   * True once the parent has resolved `currentReworkCapOverride` for this
   * item (see StuckItemDetail.tsx's identically-named prop doc comment for
   * why this can't be inferred from `currentReworkCapOverride` alone).
   * Passed straight through to StuckItemDetail.
   */
  reworkCapOverrideLoaded?: boolean;
  /**
   * Operator "Retry now" escape hatch (TriggerRemediationNow RPC) — omitted
   * disables the retry control entirely. Rejects (throws) when the row is
   * already parked or has no wired remediation action; the caller (this
   * component) surfaces that as inline error text rather than the parent
   * needing to know the specific failure shape.
   */
  onTriggerRemediationNow?: (itemId: string, reason: StuckReason) => Promise<void>;
  /**
   * Approves the item's plan (ApprovePlan RPC) — omitted disables the
   * approve control entirely. Rejects (throws) on failure, mirroring
   * onTriggerRemediationNow above, so the specific backend error message
   * reaches the caller instead of being swallowed.
   */
  // StuckItemProps was already over the 12-prop threshold before this field (pre-existing);
  // grouping into a sub-interface is a larger refactor out of scope for the Diagnose &
  // Nudge feature this file also needed touching for. Tracked as follow-up debt, not
  // newly introduced by this diff.
  onApprovePlan?: (itemId: string) => Promise<void>; // eslint-disable-line no-restricted-syntax
  /**
   * Dispatches a "Diagnose & Nudge" agent for this item (backlog item
   * 68964304). Omitted disables the control entirely. Resolves with the
   * dispatched diagnostic session's UUID so StuckItemDetail can link to it
   * directly (the session is hidden from the main list by design — this
   * link is otherwise the only way to find it). Rejects (throws) on
   * failure, mirroring onApprovePlan above. Passed straight through to
   * StuckItemDetail.
   */
  // eslint-disable-next-line no-restricted-syntax -- see onApprovePlan's identical disable above
  onDiagnose?: (itemId: string, reason: StuckReason) => Promise<string>;
  /**
   * Overrides another host's claim on a BLOCKED_BY_CLAIM item (OverrideClaimBlock
   * RPC) with an audit-logged reason of >= 5 characters. Omitted hides the
   * control. Rejects on failure so the form can show the message.
   */
  onOverrideClaimBlock?: (itemId: string, reason: string) => Promise<void>;
  /**
   * itemId from the `/unfinished?item=<itemId>` deep link (routes.unfinishedItem) —
   * when it matches this card's item.itemId, scrolls the card into view. Expansion
   * is driven by the parent (StuckItemsSection) via isExpanded, not by this prop.
   */
  focusItemId?: string; // eslint-disable-line no-restricted-syntax -- see onApprovePlan's disable above
}

/** Extracts "owner/repo" from a GitHub PR URL, for the glance-level identity line. */
function repoFromPrUrl(prUrl: string): string | null {
  const match = prUrl.match(/github\.com\/([^/]+\/[^/]+)\/pull\//);
  return match ? match[1] : null;
}

const SNOOZE_DURATION_LABELS: Record<SnoozeDuration, string> = {
  "1h": "1 hour",
  "1d": "1 day",
  "3d": "3 days",
};

/**
 * Detects a `(hover: none), (pointer: coarse)` pointer — the media query the
 * rest of the app already uses to gate hover-only chrome (design/ux.md
 * Surface 7). Returns false during SSR / before the effect runs, matching a
 * hover-capable desktop default.
 */
function useHoverUnavailable(): boolean {
  const [hoverUnavailable, setHoverUnavailable] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const mql = window.matchMedia("(hover: none), (pointer: coarse)");
    setHoverUnavailable(mql.matches);

    const listener = (e: MediaQueryListEvent) => setHoverUnavailable(e.matches);
    if (mql.addEventListener) {
      mql.addEventListener("change", listener);
      return () => mql.removeEventListener("change", listener);
    }
    // Safari <14 fallback.
    mql.addListener(listener);
    return () => mql.removeListener(listener);
  }, []);

  return hoverUnavailable;
}

/**
 * Card representing a single stuck backlog item (one BacklogStuckState row).
 * Verbatim copy of UnfinishedItem.tsx's expand/keyboard/aria-expanded shape.
 */
export function StuckItem({
  item,
  isExpanded,
  onToggleExpand,
  otherReasonsCount = 0,
  otherReasonLabels = [],
  justResolved = false,
  resolvedMessage,
  resolvedTrailingMessage,
  onSnooze,
  onReworkCapOverride,
  currentReworkCapOverride,
  reworkCapOverrideLoaded = false,
  onTriggerRemediationNow,
  onApprovePlan,
  onOverrideClaimBlock,
  onDiagnose,
  focusItemId,
}: StuckItemProps) {
  const cardRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const wasExpandedRef = useRef(isExpanded);
  const hoverUnavailable = useHoverUnavailable();

  const {
    snoozeOpen,
    snoozeDuration,
    setSnoozeDuration,
    snoozeState,
    handleSnoozeTriggerClick,
    handleSnoozeCancel,
    handleSnoozeConfirm,
    handleSnoozePickerKeyDown,
  } = useSnoozeControl(item.itemId, item.reason, onSnooze, containerRef);

  const { retryState, retryErrorMessage, handleRetryNow, isParked } = useRetryRemediation(
    item.itemId,
    item.reason,
    item.remediationAttempts,
    onTriggerRemediationNow
  );

  const {
    canOverrideClaim,
    overrideOpen,
    setOverrideOpen,
    overrideBusy,
    overrideError,
    handleOverrideConfirm,
  } = useClaimOverrideControl(item.itemId, item.reason, onOverrideClaimBlock);

  // AC 29: when this card collapses (Escape, re-click, or a parent-driven
  // toggle), keyboard focus returns to the card's own toggle control — it
  // must never be dropped to <body>.
  useEffect(() => {
    if (wasExpandedRef.current && !isExpanded) {
      cardRef.current?.focus();
    }
    wasExpandedRef.current = isExpanded;
  }, [isExpanded]);

  // /unfinished?item=<itemId> deep link (routes.unfinishedItem): scroll the
  // matching card into view once it's expanded and rendered.
  useEffect(() => {
    if (focusItemId && item.itemId === focusItemId && isExpanded) {
      cardRef.current?.scrollIntoView({ block: "center" });
    }
  }, [focusItemId, item.itemId, isExpanded]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        onToggleExpand();
      }
      if (e.key === "Escape" && isExpanded) {
        onToggleExpand();
      }
    },
    [isExpanded, onToggleExpand]
  );

  const unknown = isPrStatusUnknown(item);
  const chipLabel = unknown ? PR_STATUS_UNKNOWN_LABEL : getStuckReasonLabel(item.reason);
  const chipIcon = unknown ? PR_STATUS_UNKNOWN_ICON : getStuckReasonIcon(item.reason);
  const chipClass = unknown ? PR_STATUS_UNKNOWN_CLASS : getStuckReasonClass(item.reason);

  const repo = item.prNumber > 0 ? repoFromPrUrl(item.prUrl) : null;
  const identity =
    item.prNumber > 0
      ? `PR #${item.prNumber}${repo ? ` · ${repo}` : ""}`
      : `item ${item.itemId.slice(0, 8)}`;

  return (
    <div ref={containerRef}>
      {// analytics-exempt
      <div
        ref={cardRef}
        role="button"
        tabIndex={0}
        aria-expanded={isExpanded}
        className={`${styles.card} ${isExpanded ? styles.cardExpanded : ""} ${
          justResolved ? styles.cardResolved : ""
        }`}
        onClick={onToggleExpand}
        onKeyDown={handleKeyDown}
        data-testid="stuck-item"
        data-reason={item.reason}
        data-item-id={item.itemId}
      >
        <div className={styles.header}>
          <span
            className={`${chipClass}`}
            aria-label={chipLabel}
            data-testid="stuck-item-chip"
          >
            <span aria-hidden="true">{chipIcon}</span>
            {chipLabel}
          </span>
          {item.duplicatePending && <DuplicatePendingBadge duplicateRef={item.duplicateRef} />}
          <span className={styles.title} title={item.title}>
            {item.title}
          </span>
          <span className={styles.duration} data-testid="stuck-item-duration">
            stuck {formatStuckDuration(item.firstDetectedAt)}
          </span>
          {onTriggerRemediationNow && (
            // analytics-exempt
            <button
              type="button"
              className={`${styles.retryBtn} ${hoverUnavailable ? styles.retryBtnAlwaysOn : ""}`}
              onClick={handleRetryNow}
              disabled={isParked || retryState === "pending"}
              aria-label={
                isParked
                  ? "Retry now (disabled — remediation attempts exhausted; use Reset to try again)"
                  : "Retry remediation now"
              }
              title={
                isParked
                  ? "Automated retries have been exhausted for this item — use Reset to try again"
                  : "Immediately retry the automated fix, skipping the wait"
              }
              data-testid="stuck-item-retry-now"
            >
              {retryState === "pending" ? "Retrying…" : "Retry now"}
            </button>
          )}
          {canOverrideClaim && (
            <button
              type="button"
              className={`${styles.retryBtn} ${styles.retryBtnAlwaysOn}`}
              aria-expanded={overrideOpen}
              onClick={(e) => {
                e.stopPropagation();
                setOverrideOpen((open) => !open);
              }}
              data-testid="stuck-item-override-claim"
            >
              Override claim
            </button>
          )}
          {onSnooze && (
            // analytics-exempt
            <button
              type="button"
              className={`${styles.snoozeBtn} ${hoverUnavailable ? styles.snoozeBtnAlwaysOn : ""}`}
              onClick={handleSnoozeTriggerClick}
              aria-haspopup="true"
              aria-expanded={snoozeOpen}
              aria-label={hoverUnavailable ? "Snooze options" : "Snooze this item"}
              title="Snooze"
              data-testid="stuck-item-snooze-trigger"
            >
              {hoverUnavailable ? "⋮" : "Snooze"}
            </button>
          )}
        </div>
        <div className={styles.metaRow}>
          <span>{identity}</span>
          {unknown && (
            <span data-testid="stuck-item-last-checked">
              · last checked {formatAgo(item.lastCheckedAt)} (check failing)
            </span>
          )}
          {otherReasonsCount > 0 && (
            <span
              className={styles.otherReasonsBadge}
              title={otherReasonLabels.length > 0 ? otherReasonLabels.join(", ") : undefined}
              data-testid="stuck-item-other-reasons-badge"
            >
              · also stuck for {otherReasonsCount} other reason{otherReasonsCount !== 1 ? "s" : ""} ⓘ
            </span>
          )}
        </div>
        {retryState === "error" && retryErrorMessage && (
          <div className={styles.retryError} data-testid="stuck-item-retry-error">
            Retry failed: {retryErrorMessage}
          </div>
        )}
      </div>}

      {overrideOpen && canOverrideClaim && (
        <div onClick={(e) => e.stopPropagation()} onKeyDown={(e) => e.stopPropagation()}>
          <ClaimOverrideForm
            label="Reason for working on this despite the other host's claim (required)"
            confirmLabel="Override claim block"
            onConfirm={handleOverrideConfirm}
            onCancel={() => setOverrideOpen(false)}
            busy={overrideBusy}
            errorMessage={overrideError}
          />
        </div>
      )}

      {snoozeOpen && onSnooze && (
        <div
          className={styles.snoozePicker}
          role="group"
          aria-label="Snooze duration"
          data-testid="stuck-item-snooze-picker"
          onClick={(e) => e.stopPropagation()}
          onKeyDown={handleSnoozePickerKeyDown}
        >
          <div className={styles.snoozeOptions}>
            {(Object.keys(SNOOZE_DURATION_LABELS) as SnoozeDuration[]).map((d) => (
              <label key={d} className={styles.snoozeOptionLabel}>
                <input
                  type="radio"
                  name={`snooze-duration-${item.itemId}-${item.reason}`}
                  value={d}
                  checked={snoozeDuration === d}
                  onChange={() => setSnoozeDuration(d)}
                  data-testid={`stuck-item-snooze-option-${d}`}
                />
                {SNOOZE_DURATION_LABELS[d]}
              </label>
            ))}
          </div>

          {snoozeState === "error" && (
            <div className={styles.snoozeErrorRow} data-testid="stuck-item-snooze-error">
              Couldn&apos;t snooze — try again
            </div>
          )}

          <div className={styles.snoozeActions}>
            {// analytics-exempt
            <button
              type="button"
              className={styles.snoozeCancelBtn}
              onClick={handleSnoozeCancel}
              data-testid="stuck-item-snooze-cancel"
            >
              Cancel
            </button>}
            {// analytics-exempt
            <button
              type="button"
              className={styles.snoozeConfirmBtn}
              onClick={handleSnoozeConfirm}
              disabled={snoozeState === "pending"}
              data-testid="stuck-item-snooze-confirm"
            >
              {snoozeState === "pending" ? "Snoozing…" : snoozeState === "error" ? "Retry" : "Confirm"}
            </button>}
          </div>
        </div>
      )}

      {justResolved && (
        <div className={styles.resolvedBanner} data-testid="stuck-item-resolved-banner">
          ✓ {resolvedMessage || "This item was just resolved."}{" "}
          {resolvedTrailingMessage || "It will be removed from this list shortly."}
        </div>
      )}

      {isExpanded && !justResolved && (
        <StuckItemDetail
          item={item}
          onReworkCapOverride={onReworkCapOverride}
          currentReworkCapOverride={currentReworkCapOverride}
          reworkCapOverrideLoaded={reworkCapOverrideLoaded}
          onApprovePlan={onApprovePlan}
          onDiagnose={onDiagnose}
        />
      )}
    </div>
  );
}
